function applyUiPreviewMode(){
  const host = window.location.hostname;
  if(host !== '127.0.0.1' && host !== 'localhost') return;
  const preview = new URLSearchParams(window.location.search).get('ui');
  if(!preview) return;
  if(preview === 'basic'){
    state.mode = 'play';
    state.basicPoints = Math.max(state.basicPoints, 8);
    state.basicPickerOpen = true;
    state.maxHp = safeHpMax();
    state.hp = state.maxHp;
    state.spawnTimer = 999;
  }else if(preview === 'special'){
    state.mode = 'levelup';
    state.skillPoints = Math.max(state.skillPoints, 1);
    state.upgradeOptions = ['barrelDouble', 'ammoDrum', 'quickLoader'];
  }else if(preview === 'homeUpgrade'){
    state.mode = 'homeUpgrade';
    state.tokens = Math.max(state.tokens, 1800);
  }else if(preview === 'store'){
    state.mode = 'store';
    state.tokens = Math.max(state.tokens, 1800);
  }else if(preview === 'garage'){
    state.mode = 'garage';
  }else if(preview === 'gacha'){
    state.mode = 'gacha';
    state.tokens = Math.max(state.tokens, GACHA_COST);
  }else if(preview === 'ranking'){
    state.mode = 'ranking';
  }else if(preview === 'settings'){
    state.mode = 'settings';
  }else if(preview === 'pause'){
    state.mode = 'pause';
  }else if(preview === 'boss'){
    state.mode = 'play';
    applySceneVisualMode('play');
    state.wave = Math.max(state.wave, 10);
    state.maxHp = safeHpMax();
    state.hp = state.maxHp;
    state.roll = 0;
    state.prevRoll = 0;
    clearRunObjects();
    spawnBoss();
    const boss = enemies.find(enemy => enemy.boss);
    if(boss){
      boss.z = BOSS_TARGET_Z;
      boss.prevZ = boss.z;
      boss.angle = 0;
      boss.prevAngle = boss.angle;
      boss.sin = Math.sin(boss.angle);
      boss.cos = Math.cos(boss.angle);
      boss.spawnZ = BOSS_SIGHT_Z;
      setPipePositionFromTrig(boss.root, boss.sin, boss.cos, boss.z, boss.radial);
      applyEnemyVisual(boss, 0);
      revealEnemyHpBar(boss, boss.maxHp, Math.max(1, Math.floor(boss.maxHp * .18)));
      spawnBossShard(boss);
    }
  }else if(preview === 'bossChase'){
    state.mode = 'play';
    applySceneVisualMode('play');
    state.wave = Math.max(state.wave, 10);
    state.maxHp = safeHpMax();
    state.hp = state.maxHp;
    state.roll = .92;
    state.prevRoll = .92;
    state.rollVel = 0;
    state.input = 0;
    clearRunObjects();
    spawnBoss();
    const boss = enemies.find(enemy => enemy.boss);
    if(boss){
      boss.z = BOSS_TARGET_Z;
      boss.prevZ = boss.z;
      boss.angle = -.72;
      boss.prevAngle = boss.angle;
      boss.sin = Math.sin(boss.angle);
      boss.cos = Math.cos(boss.angle);
      boss.spawnZ = BOSS_SIGHT_Z;
      setPipePositionFromTrig(boss.root, boss.sin, boss.cos, boss.z, boss.radial);
      applyEnemyVisual(boss, 0);
    }
  }else if(preview === 'hit'){
    state.mode = 'play';
    applySceneVisualMode('play');
    state.wave = Math.max(state.wave, 3);
    state.maxHp = safeHpMax();
    state.hp = state.maxHp;
    state.roll = 0;
    state.prevRoll = 0;
    clearRunObjects();
    spawnEnemy(0);
    const target = enemies[0];
    if(target){
      target.z = -48;
      target.prevZ = target.z;
      target.angle = 0;
      target.prevAngle = target.angle;
      target.sin = Math.sin(target.angle);
      target.cos = Math.cos(target.angle);
      target.maxHp = 999;
      target.initialHp = 999;
      target.hp = 620;
      target.spawnZ = PIPE_Z_FAR + 24;
      target.hitFlash = 1;
      target.hitCue = 1;
      target.hitCueColor = 0xffd36a;
      setPipePositionFromTrig(target.root, target.sin, target.cos, target.z, target.radial);
      applyEnemyVisual(target, 0);
      const previewBullet = {crit:false, pierce:0, z:target.z, prevZ:target.z + 1};
      triggerHitConfirm(target, previewBullet, target.type.color);
      revealEnemyHpBar(target, 999, 379);
      spawnBulletImpact(target, previewBullet, target.angle, target.z, target.type.color, 2);
    }
  }else if(preview === 'reload'){
    state.mode = 'play';
    applySceneVisualMode('play');
    state.wave = Math.max(state.wave, 3);
    state.maxHp = safeHpMax();
    state.hp = state.maxHp;
    state.roll = 0;
    state.prevRoll = 0;
    state.spawnTimer = 999;
    clearRunObjects();
    state.magazine = magazineSize();
    state.ammo = 0;
    state.reloading = true;
    state.reloadTotal = reloadDuration();
    state.reloadTimer = state.reloadTotal * .54;
  }else if(preview === 'kill'){
    state.mode = 'play';
    applySceneVisualMode('play');
    state.wave = Math.max(state.wave, 4);
    state.maxHp = safeHpMax();
    state.hp = state.maxHp;
    state.roll = 0;
    state.prevRoll = 0;
    state.spawnTimer = 999;
    clearRunObjects();
    spawnEnemy(0);
    const target = enemies[0];
    if(target){
      target.z = -48;
      target.prevZ = target.z;
      target.angle = 0;
      target.prevAngle = target.angle;
      target.sin = Math.sin(target.angle);
      target.cos = Math.cos(target.angle);
      target.baseRadial = ENEMY_RAISED_RADIAL;
      target.radial = ENEMY_RAISED_RADIAL;
      target.spawnZ = PIPE_Z_FAR + 24;
      setPipePositionFromTrig(target.root, target.sin, target.cos, target.z, target.radial);
      applyEnemyVisual(target, 0);
      removeEnemy(0, true);
    }
  }else if(preview === 'collision' || preview === 'wing-collision'){
    state.mode = 'play';
    applySceneVisualMode('play');
    state.wave = Math.max(state.wave, 3);
    state.maxHp = safeHpMax();
    state.hp = state.maxHp;
    state.roll = 0;
    state.prevRoll = 0;
    state.spawnTimer = 999;
    clearRunObjects();
    spawnEnemy(0);
    const target = enemies[0];
    if(target){
      const wingPreviewAngle = preview === 'wing-collision' ? .15 : 0;
      target.z = PLAYER_Z - 3.8;
      target.prevZ = PLAYER_Z - 6.8;
      target.angle = wingPreviewAngle;
      target.prevAngle = wingPreviewAngle;
      target.sin = Math.sin(target.angle);
      target.cos = Math.cos(target.angle);
      target.baseRadial = ENEMY_RAISED_RADIAL;
      target.prevRadial = enemyApproachRadial(target, target.prevZ);
      target.radial = enemyApproachRadial(target, target.z);
      target.spawnZ = PIPE_Z_FAR + 24;
      setPipePositionFromTrig(target.root, target.sin, target.cos, target.z, target.radial);
      applyEnemyVisual(target, 0);
    }
  }else if(preview === 'shotgun'){
    state.mode = 'play';
    applySceneVisualMode('play');
    state.wave = Math.max(state.wave, 4);
    state.maxHp = safeHpMax();
    state.hp = state.maxHp;
    state.roll = 0;
    state.prevRoll = 0;
    state.input = 0;
    state.firing = 999;
    clearRunObjects();
    state.specialUpgrades.barrelShotgun = 1;
    fireShot();
    for(let i = 0; i < 18; i++) updateBullets(1 / 60);
  }else if(preview === 'gatling'){
    state.mode = 'play';
    applySceneVisualMode('play');
    state.wave = Math.max(state.wave, 4);
    state.maxHp = safeHpMax();
    state.hp = state.maxHp;
    state.roll = 0;
    state.prevRoll = 0;
    state.input = 0;
    state.firing = 999;
    clearRunObjects();
    state.specialUpgrades.barrelGatling = 1;
    for(let i = 0; i < 8; i++){
      fireShot();
      updateBullets(1 / 26);
    }
  }else if(preview === 'crash'){
    state.mode = 'play';
    applySceneVisualMode('play');
    state.wave = Math.max(state.wave, 4);
    state.maxHp = safeHpMax();
    state.hp = state.maxHp;
    state.roll = 0;
    state.prevRoll = 0;
    state.input = 0;
    state.firing = 999;
    clearRunObjects();
    state.hp = 0;
    beginDeathCrash();
  }else if(preview === 'dead'){
    state.mode = 'dead';
    state.score = Math.max(state.score, 12840);
    state.wave = Math.max(state.wave, 9);
    state.runTokenGain = Math.max(state.runTokenGain, 160);
  }
}

function freshStatMap(){
  const ids = new Set([...HOME_UPGRADE_IDS, ...BASIC_SKILL_IDS]);
  return Object.fromEntries([...ids].map(id => [id, 0]));
}

function freshHomeUpgradeMap(){
  return Object.fromEntries(HOME_UPGRADE_IDS.map(id => [id, 0]));
}

function freshSpecialUpgradeMap(){
  return Object.fromEntries(SPECIAL_UPGRADE_DEFS.map(def => [def.id, 0]));
}

function freshEquippedParts(){
  return Object.fromEntries(PART_TYPES.map(type => [type, Array(3).fill(null)]));
}

function freshGarageState(){
  const equippedParts = freshEquippedParts();
  equippedParts.barrel[0] = 'barrel_pulse';
  equippedParts.innerFrame[0] = 'frame_vital';
  equippedParts.drone[0] = 'drone_scout';
  return {
    partsStoreVersion: 1,
    ownedShips: {[DEFAULT_SHIP_ID]: 1},
    selectedShipId: DEFAULT_SHIP_ID,
    ownedParts: Object.fromEntries(STARTER_PART_IDS.map(id => [id, 1])),
    equippedParts
  };
}

function normalizeGarageState(raw){
  const base = freshGarageState();
  const ownedShips = {...base.ownedShips, ...(raw?.ownedShips || {})};
  let selectedShipId = SHIP_BY_ID[raw?.selectedShipId] && ownedShips[raw.selectedShipId] ? raw.selectedShipId : DEFAULT_SHIP_ID;
  ownedShips[DEFAULT_SHIP_ID] = 1;
  if(!ownedShips[selectedShipId]) selectedShipId = DEFAULT_SHIP_ID;

  const rawOwnedParts = raw?.ownedParts || {};
  const legacyFreeParts = !raw?.partsStoreVersion && Object.keys(rawOwnedParts).length >= PART_DEFS.length;
  const ownedParts = legacyFreeParts ? {...base.ownedParts} : {...base.ownedParts, ...rawOwnedParts};
  for(const id of STARTER_PART_IDS) ownedParts[id] = Math.max(1, Number(ownedParts[id]) || 1);
  for(const part of PART_DEFS) ownedParts[part.id] = Math.max(0, Number(ownedParts[part.id]) || 0);

  if(legacyFreeParts){
    for(const parts of Object.values(raw?.equippedParts || {})){
      if(!Array.isArray(parts)) continue;
      for(const id of parts){
        if(PART_BY_ID[id]) ownedParts[id] = 1;
      }
    }
  }

  const equippedParts = freshEquippedParts();
  for(const type of PART_TYPES){
    const source = Array.isArray(raw?.equippedParts?.[type]) ? raw.equippedParts[type] : [];
    const seen = new Set();
    for(let i=0;i<3;i++){
      const id = source[i];
      const part = PART_BY_ID[id];
      if(!part || part.type !== type || !ownedParts[id] || seen.has(id)) continue;
      equippedParts[type][i] = id;
      seen.add(id);
    }
  }
  return {partsStoreVersion:1, ownedShips, selectedShipId, ownedParts, equippedParts};
}

function freshCosmeticState(){
  return {
    owned: Object.fromEntries(Object.values(DEFAULT_COSMETICS).map(id => [id, 1])),
    equipped: {...DEFAULT_COSMETICS}
  };
}

function normalizeCosmeticState(raw){
  const base = freshCosmeticState();
  const owned = {...base.owned, ...(raw?.owned || {})};
  const equipped = {...base.equipped};
  for(const type of Object.keys(DEFAULT_COSMETICS)){
    const id = raw?.equipped?.[type];
    equipped[type] = COSMETIC_BY_ID[id]?.type === type && owned[id] ? id : DEFAULT_COSMETICS[type];
    owned[equipped[type]] = Math.max(1, Number(owned[equipped[type]]) || 1);
  }
  return {owned, equipped};
}

function freshSettingsState(){
  return {
    controlMode: CONTROL_MODE_DEFAULT,
    controlModePinned: false,
    unlimitedTokens: false
  };
}

function normalizeSettingsState(raw){
  const base = freshSettingsState();
  const rawMode = CONTROL_MODES[raw?.controlMode] ? raw.controlMode : null;
  const pinned = !!raw?.controlModePinned;
  const controlMode = pinned && rawMode ? rawMode : base.controlMode;
  return {
    ...base,
    controlMode,
    controlModePinned: pinned,
    unlimitedTokens: !!raw?.unlimitedTokens
  };
}

function loadSave(){
  try{
    const raw = localStorage.getItem(SAVE_KEY);
    if(!raw) return {highScore:0,bestWave:1,tokens:START_TOKENS,homeUpgrades:freshHomeUpgradeMap(),garage:freshGarageState(),cosmetics:freshCosmeticState(),settings:freshSettingsState()};
    const parsed = JSON.parse(raw);
    return {
      highScore: Math.max(0, Number(parsed.highScore) || 0),
      bestWave: Math.max(1, Number(parsed.bestWave) || 1),
      tokens: Math.max(0, parsed.tokens == null ? START_TOKENS : Number(parsed.tokens) || 0),
      homeUpgrades: {...freshHomeUpgradeMap(), ...(parsed.homeUpgrades || {})},
      garage: normalizeGarageState(parsed.garage),
      cosmetics: normalizeCosmeticState(parsed.cosmetics),
      settings: normalizeSettingsState(parsed.settings)
    };
  }catch{
    return {highScore:0,bestWave:1,tokens:START_TOKENS,homeUpgrades:freshHomeUpgradeMap(),garage:freshGarageState(),cosmetics:freshCosmeticState(),settings:freshSettingsState()};
  }
}

function saveProgress(){
  localStorage.setItem(SAVE_KEY, JSON.stringify({
    highScore: state.highScore,
    bestWave: state.bestWave,
    tokens: state.tokens,
    homeUpgrades: state.homeUpgrades,
    garage: state.garage,
    cosmetics: state.cosmetics,
    settings: state.settings
  }));
}

function saveRun(){
  state.runTokenGain = calculateTokenReward();
  state.tokens += state.runTokenGain;
  state.highScore = Math.max(state.highScore, state.score);
  state.bestWave = Math.max(state.bestWave, state.wave);
  upsertScore({
    playerId: 'local:guest',
    name: 'GUEST',
    score: state.score,
    wave: state.wave
  });
  saveProgress();
}

function controlMode(){
  return CONTROL_MODES[state.settings?.controlMode] ? state.settings.controlMode : CONTROL_MODE_DEFAULT;
}

function controlModeDef(){
  return CONTROL_MODES[controlMode()] || CONTROL_MODES[CONTROL_MODE_DEFAULT];
}

function setControlMode(mode){
  if(!CONTROL_MODES[mode]) return;
  if(!state.settings) state.settings = freshSettingsState();
  if(state.settings.controlMode === mode) return;
  state.settings.controlMode = mode;
  state.settings.controlModePinned = true;
  state.pointer = 0;
  state.pointerThrottle = 0;
  resetTurnHold();
  resetTouchStick();
  saveProgress();
  renderUi2();
}

function hasUnlimitedTokens(){
  return !!state.settings?.unlimitedTokens;
}

function setUnlimitedTokens(enabled){
  if(!state.settings) state.settings = freshSettingsState();
  state.settings.unlimitedTokens = !!enabled;
  saveProgress();
  renderUi2();
}

function canSpendTokens(cost){
  return hasUnlimitedTokens() || state.tokens >= cost;
}

function spendTokens(cost){
  if(!Number.isFinite(cost) || cost < 0) return false;
  if(!canSpendTokens(cost)) return false;
  if(!hasUnlimitedTokens()) state.tokens -= cost;
  return true;
}

function skillRerollCost(){
  return SKILL_REROLL_BASE_COST + state.skillRerolls * SKILL_REROLL_COST_STEP;
}

function rerollSkillOptions(){
  if(state.mode !== 'levelup' || state.skillPoints <= 0) return;
  const cost = skillRerollCost();
  if(!spendTokens(cost)) return;
  const next = rollUpgradeOptions();
  if(!next.length) return;
  state.skillRerolls++;
  state.upgradeOptions = next;
  saveProgress();
  renderUi2();
}

function resetSaveData(){
  const confirmed = window.confirm?.('保存データとランキングを初期化します。よろしいですか？');
  if(confirmed === false) return;
  clearRunObjects();
  state.mode = 'home';
  state.wave = 1;
  state.waveTime = 0;
  state.score = 0;
  state.hp = 100;
  state.maxHp = 100;
  state.xp = 0;
  state.level = 1;
  state.skillPoints = 0;
  state.skillRerolls = 0;
  state.basicPoints = 0;
  state.basicPickerOpen = false;
  state.basicPointMeter = 0;
  state.tokens = START_TOKENS;
  state.runTokenGain = 0;
  state.runTime = 0;
  state.kills = 0;
  state.statLevels = freshStatMap();
  state.homeUpgrades = freshHomeUpgradeMap();
  state.specialUpgrades = freshSpecialUpgradeMap();
  state.upgradeOptions = [];
  state.highScore = 0;
  state.bestWave = 1;
  state.garage = freshGarageState();
  state.cosmetics = freshCosmeticState();
  state.settings = freshSettingsState();
  state.settingsReturnMode = 'home';
  state.lastGacha = null;
  state.storeCategory = 'ship';
  state.storePreviewShipId = DEFAULT_SHIP_ID;
  state.deathTimer = 0;
  state.playerDeathAge = 0;
  state.deathSaved = false;
  state.keyboardThrottle = 0;
  state.pointerThrottle = 0;
  state.throttle = 0;
  invalidateStatCache();
  invalidateLoadoutCache();
  resetWeaponState(true);
  cosmeticBuffCache = null;
  markHomeShipPartsDirty();
  localStorage.removeItem(RANKING_KEY);
  saveProgress();
  applyCosmetics();
  renderUi2();
  syncCanvasVisibility();
}

function resetTurnHold(){
  state.turnHoldDir = 0;
  state.turnHoldTime = 0;
}

function heldTurnControl(dt){
  const input = Number(state.input) || 0;
  const amount = Math.abs(input);
  if(amount < CONTROL_HOLD_DEADZONE){
    resetTurnHold();
    return {turn:1, response:1};
  }

  const dir = input > 0 ? 1 : -1;
  if(state.turnHoldDir === dir){
    state.turnHoldTime = Math.min(CONTROL_HOLD_RAMP_DELAY + CONTROL_HOLD_RAMP_TIME, (state.turnHoldTime || 0) + dt);
  }else{
    state.turnHoldDir = dir;
    state.turnHoldTime = dt;
  }

  const held = Math.max(0, (state.turnHoldTime || 0) - CONTROL_HOLD_RAMP_DELAY);
  const ramp = smoothstep(clamp(held / CONTROL_HOLD_RAMP_TIME, 0, 1));
  const inputWeight = clamp((amount - CONTROL_HOLD_DEADZONE) / (1 - CONTROL_HOLD_DEADZONE), 0, 1);
  const boost = ramp * (.50 + inputWeight * .50);
  return {
    turn: 1 + CONTROL_HOLD_TURN_BOOST_MAX * boost,
    response: 1 + CONTROL_HOLD_RESPONSE_BOOST_MAX * boost
  };
}

function statDef(id){
  return HOME_UPGRADE_DEFS[id] || BASIC_STAT_DEFS_BY_ID[id] || BASIC_STAT_DEFS[0];
}

function homeUpgradeDef(id){
  return HOME_UPGRADE_DEFS[id] || HOME_UPGRADE_DEFS.fireRate;
}

function homeUpgradeLevel(id){
  const lv = Math.max(0, Math.floor(Number(state.homeUpgrades?.[id]) || 0));
  return homeUpgradeDef(id).tier === 'base' ? Math.min(HOME_UPGRADE_CAP, lv) : lv;
}

function isHomeUpgradeUnlocked(id){
  const def = homeUpgradeDef(id);
  return !def.parent || homeUpgradeLevel(def.parent) >= HOME_UPGRADE_CAP;
}

function isHomeUpgradeMaxed(id){
  const def = homeUpgradeDef(id);
  return def.tier === 'base' && homeUpgradeLevel(id) >= HOME_UPGRADE_CAP;
}

function runBasicLevel(id){
  const def = BASIC_SKILL_DEFS_BY_ID[id];
  const lv = Math.max(0, Math.floor(Number(state.statLevels?.[id]) || 0));
  if(!def) return 0;
  return def.tier === 'base' ? Math.min(def.cap || RUN_BASIC_CAP, lv) : lv;
}

function isRunBasicUnlocked(id){
  const def = BASIC_SKILL_DEFS_BY_ID[id];
  if(!def) return false;
  if(def.tier !== 'advanced') return true;
  return !!def.parent && runBasicLevel(def.parent) >= (BASIC_SKILL_DEFS_BY_ID[def.parent]?.cap || RUN_BASIC_CAP);
}

function isRunBasicMaxed(id){
  const def = BASIC_SKILL_DEFS_BY_ID[id];
  return !!def && def.tier === 'base' && runBasicLevel(id) >= (def.cap || RUN_BASIC_CAP);
}

function statLevel(id){
  if(!statLevelCache) statLevelCache = {};
  if(statLevelCache[id] !== undefined) return statLevelCache[id];
  const level = Math.max(0, Number(state.statLevels[id]) || 0) + homeUpgradeLevel(id);
  statLevelCache[id] = level;
  return level;
}

function specialUpgradeDef(id){
  return SPECIAL_UPGRADE_DEFS_BY_ID[id];
}

function specialUpgradeLevel(id){
  return Math.max(0, Math.floor(Number(state.specialUpgrades?.[id]) || 0));
}

function invalidateStatCache(){
  statLevelCache = null;
  statMultCache = null;
  invalidateWeaponCache();
}

function invalidateWeaponCache(){
  weaponRuntimeCache = null;
}

function selectedSpecialInFamily(family){
  return SPECIAL_UPGRADE_DEFS.find(def => def.family === family && specialUpgradeLevel(def.id) > 0)?.id || null;
}

function selectedSpecialSlotDefs(){
  return SPECIAL_UPGRADE_DEFS.filter(def => specialUpgradeLevel(def.id) > 0);
}

function specialUpgradeIcon(def, className = 'special-icon'){
  const id = def?.id || 'default';
  const cacheKey = `${id}|${className}`;
  if(specialIconMarkupCache.has(cacheKey)) return specialIconMarkupCache.get(cacheKey);
  const svg = SPECIAL_ICON_SVG[id] || SPECIAL_ICON_SVG.default;
  const markup = `<span class="${className}" aria-hidden="true">${svg}</span>`;
  specialIconMarkupCache.set(cacheKey, markup);
  return markup;
}

function canOfferSpecialUpgrade(id){
  const def = specialUpgradeDef(id);
  if(!def) return false;
  if(specialUpgradeLevel(id) >= def.max) return false;
  const selected = selectedSpecialInFamily(def.family);
  if(selected && selected !== id) return false;
  if(!selected && selectedSpecialSlotDefs().length >= SPECIAL_SLOT_LIMIT) return false;
  return true;
}

function runUpgradeDef(id){
  return specialUpgradeDef(id) || statDef(id);
}

function runUpgradeLevel(id){
  return specialUpgradeDef(id) ? specialUpgradeLevel(id) : Math.max(0, Number(state.statLevels[id]) || 0);
}

function barrelFireBoost(){
  if(specialUpgradeLevel('barrelGatling') > 0) return 2.35;
  if(specialUpgradeLevel('barrelSniper') > 0) return .50;
  if(specialUpgradeLevel('barrelShotgun') > 0) return .66;
  if(specialUpgradeLevel('barrelMultishot') > 0) return .86;
  if(specialUpgradeLevel('barrelDouble') > 0) return .90;
  return 1;
}

function specialFireRateMultiplier(){
  return 1 + specialUpgradeLevel('overclockCore') * .08;
}

function specialDamageMultiplier(){
  let mult = 1 + specialUpgradeLevel('powerShot') * .13;
  mult *= 1 + specialUpgradeLevel('focusLens') * .075;
  mult *= Math.max(.84, 1 - specialUpgradeLevel('wideBore') * .045);
  mult *= Math.max(.88, 1 - specialUpgradeLevel('pierceShot') * .035);
  const adrenaline = specialUpgradeLevel('adrenaline');
  if(adrenaline > 0){
    const missingHp = 1 - Math.max(0, Math.min(1, visibleHp() / visibleHpMax()));
    mult *= 1 + adrenaline * .18 * missingHp;
  }
  return mult;
}

function bulletPierceCount(){
  return specialUpgradeLevel('pierceShot');
}

function specialBulletSpeedMultiplier(){
  return 1 + specialUpgradeLevel('focusLens') * .10;
}

function specialRangeMultiplier(){
  return 1 + specialUpgradeLevel('focusLens') * .07;
}

function specialBulletRadiusMultiplier(){
  return 1 + specialUpgradeLevel('wideBore') * .13;
}

function specialDefenseMultiplier(){
  return Math.max(.64, 1 - specialUpgradeLevel('energyShield') * .075);
}

function specialRegenPerSecond(){
  return specialUpgradeLevel('repairNanites') * .34;
}

function specialSpeedMultiplier(){
  return 1 + specialUpgradeLevel('afterburnerCore') * .09;
}

function specialEvasionBonus(){
  return specialUpgradeLevel('phaseVeil') * .04 + specialUpgradeLevel('afterburnerCore') * .025;
}

function specialXpMultiplier(){
  return 1 + specialUpgradeLevel('xpSiphon') * .075;
}

function specialMagazineBonus(){
  return specialUpgradeLevel('ammoDrum') * MAGAZINE_SPECIAL_BONUS + (specialUpgradeLevel('barrelGatling') > 0 ? 6 : 0);
}

function specialReloadMultiplier(){
  return 1 + specialUpgradeLevel('quickLoader') * .13 + specialUpgradeLevel('overclockCore') * .025;
}

function weaponRuntimeStats(){
  if(weaponRuntimeCache) return weaponRuntimeCache;
  const magazine = clamp(
    Math.round((MAGAZINE_BASE + statLevel('magazine') * MAGAZINE_STAT_BONUS + specialMagazineBonus()) * loadoutMult('magazine')),
    6,
    MAGAZINE_MAX
  );
  const reloadSpeed = statMult('reload', RELOAD_STAT_STEP) * specialReloadMultiplier() * loadoutMult('reload');
  const reload = Math.max(RELOAD_DURATION_MIN, RELOAD_DURATION_BASE / Math.max(.1, reloadSpeed));
  const fireBoost = (1 + statLevel('fireRate') * FIRE_RATE_STAT_STEP) * barrelFireBoost() * specialFireRateMultiplier() * loadoutMult('fireRate');
  const ammoCost = specialUpgradeLevel('barrelShotgun') > 0 ? 3
    : specialUpgradeLevel('barrelSniper') > 0 ? 2
      : specialUpgradeLevel('barrelMultishot') > 0 ? 2
        : specialUpgradeLevel('barrelDouble') >= 3 ? 2
          : 1;
  weaponRuntimeCache = {magazine, reload, fireBoost, ammoCost};
  return weaponRuntimeCache;
}

function magazineSize(){
  return weaponRuntimeStats().magazine;
}

function reloadDuration(){
  return weaponRuntimeStats().reload;
}

function syncMagazineCapacity(fillGained = false){
  const next = magazineSize();
  const previous = Math.max(0, Math.floor(Number(state.magazine) || next));
  const current = Number.isFinite(Number(state.ammo)) ? Math.max(0, Math.floor(Number(state.ammo))) : next;
  state.magazine = next;
  state.ammo = fillGained && next > previous ? Math.min(next, current + next - previous) : Math.min(next, current);
  if(state.reloading && state.ammo >= next){
    state.reloading = false;
    state.reloadTimer = 0;
  }
  return next;
}

function resetWeaponState(fill = true){
  const capacity = syncMagazineCapacity(false);
  state.ammo = fill ? capacity : Math.min(capacity, Math.max(0, Math.floor(Number(state.ammo) || 0)));
  state.reloadTimer = 0;
  state.reloadTotal = reloadDuration();
  state.reloading = false;
  state.firing = 0;
}

function isFireInputActive(){
  return (Number(state.throttle) || 0) > FIRE_FORWARD_INPUT_DEADZONE;
}

function isBackInputActive(){
  return (Number(state.throttle) || 0) < -FIRE_BACK_INPUT_DEADZONE;
}

function shotAmmoCost(){
  return weaponRuntimeStats().ammoCost;
}

function beginReload(extraTime = 0){
  const capacity = syncMagazineCapacity(false);
  if(state.reloading || state.ammo >= capacity) return false;
  const duration = reloadDuration() + Math.max(0, Number(extraTime) || 0);
  state.reloading = true;
  state.reloadTotal = duration;
  state.reloadTimer = duration;
  return true;
}

function finishReload(){
  state.ammo = syncMagazineCapacity(false);
  state.reloading = false;
  state.reloadTimer = 0;
  state.reloadTotal = reloadDuration();
}

function updateWeaponReload(dt){
  syncMagazineCapacity(false);
  if(!state.reloading) return false;
  state.reloadTimer = Math.max(0, (Number(state.reloadTimer) || 0) - dt);
  if(state.reloadTimer > 0) return false;
  finishReload();
  return true;
}

function weaponFireInterval(){
  const waveReduction = Math.min(FIRE_INTERVAL_WAVE_REDUCTION_MAX, state.wave * FIRE_INTERVAL_WAVE_REDUCTION);
  return Math.max(FIRE_INTERVAL_MIN, (FIRE_INTERVAL_BASE - waveReduction) / Math.max(.1, weaponRuntimeStats().fireBoost));
}

function updateWeaponFire(dt){
  const capacity = syncMagazineCapacity(false);
  updateWeaponReload(dt);
  if(isBackInputActive() && state.ammo < capacity && !state.reloading) beginReload(0);
  if(!isFireInputActive() || state.reloading){
    state.firing = 0;
    return;
  }
  state.firing -= dt;
  if(state.firing > 0) return;
  const fireInterval = weaponFireInterval();
  let volleys = 0;
  while(state.firing <= 0 && volleys < 3){
    const cost = shotAmmoCost();
    if(state.ammo < cost){
      beginReload(state.ammo <= 0 ? RELOAD_EMPTY_PENALTY : 0);
      break;
    }
    state.ammo -= cost;
    fireShot();
    state.firing += fireInterval;
    volleys++;
    if(state.ammo <= 0){
      beginReload(RELOAD_EMPTY_PENALTY);
      break;
    }
  }
  if(state.firing <= 0) state.firing = fireInterval;
}

function visibleAmmo(){
  return clamp(Math.floor(Number(state.ammo) || 0), 0, magazineSize());
}

function ammoFillPercent(){
  const capacity = Math.max(1, magazineSize());
  if(state.reloading){
    const total = Math.max(.001, Number(state.reloadTotal) || reloadDuration());
    return clamp((1 - (Number(state.reloadTimer) || 0) / total) * 100, 0, 100);
  }
  return visibleAmmo() / capacity * 100;
}

function ammoHudLabel(){
  if(state.reloading) return 'RELOAD';
  if(isBackInputActive()) return 'LOAD';
  if(visibleAmmo() <= 0) return 'EMPTY';
  return 'AMMO';
}

function ammoHudText(){
  if(state.reloading) return `${Math.max(0, Number(state.reloadTimer) || 0).toFixed(1)}s`;
  return `${visibleAmmo()}/${magazineSize()}`;
}

function specialTargetDamageMultiplier(enemy){
  const level = specialUpgradeLevel('targetBeacon');
  if(level <= 0 || !enemy) return 1;
  const angleGap = Math.abs(signedAngleDelta(enemy.angle ?? 0, state.roll));
  return angleGap < (.18 + level * .025) ? 1 + level * .06 : 1;
}

function currentShip(){
  return SHIP_BY_ID[state.garage?.selectedShipId] || SHIP_BY_ID[DEFAULT_SHIP_ID];
}

function currentShipVisualProfile(){
  return SHIP_VISUAL_PROFILES[currentShip().id] || SHIP_VISUAL_PROFILES[DEFAULT_SHIP_ID];
}

function storePreviewShip(){
  return SHIP_BY_ID[state.storePreviewShipId] || currentShip();
}

function visualPreviewShip(){
  return state.mode === 'store' ? storePreviewShip() : currentShip();
}

function shipOwned(id){
  return !!state.garage?.ownedShips?.[id];
}

function shipMult(key){
  return Number(currentShip().mult?.[key]) || 1;
}

function shipSlotCount(type, ship = currentShip()){
  return Math.max(0, Math.min(3, Math.floor(Number(ship.slots?.[type]) || 0)));
}

function invalidateLoadoutCache(){
  loadoutBuffCache = null;
  loadoutMultCache = null;
  invalidateWeaponCache();
}

function rebuildLoadoutBuffCache(){
  const ship = currentShip();
  const power = Number(ship.partPower) || 1;
  const cache = {};
  for(const type of PART_TYPES){
    const slots = shipSlotCount(type, ship);
    const equipped = state.garage?.equippedParts?.[type] || [];
    for(let i=0;i<slots;i++){
      const part = PART_BY_ID[equipped[i]];
      if(!part?.buff) continue;
      for(const key in part.buff){
        cache[key] = (cache[key] || 0) + part.buff[key] * power;
      }
    }
  }
  loadoutBuffCache = cache;
  loadoutMultCache = {};
}

function loadoutBuff(key){
  if(!loadoutBuffCache) rebuildLoadoutBuffCache();
  return Math.min(.24, loadoutBuffCache[key] || 0);
}

function loadoutMult(key){
  if(!loadoutMultCache) loadoutMultCache = {};
  if(loadoutMultCache[key] == null) loadoutMultCache[key] = shipMult(key) * (1 + loadoutBuff(key));
  return loadoutMultCache[key];
}

function refreshLoadoutVitals(){
  const before = visibleHpMax();
  const next = safeHpMax();
  state.maxHp = next;
  if(state.mode === 'play'){
    state.hp = Math.min(next, state.hp + Math.max(0, next - before));
  }else{
    state.hp = Math.min(next, state.hp || next);
  }
}

function cosmeticBuff(key){
  if(!cosmeticBuffCache){
    cosmeticBuffCache = {};
    for(const id of Object.keys(state.cosmetics?.owned || {})){
      const item = COSMETIC_BY_ID[id];
      if(!item?.buff) continue;
      for(const [buffKey, value] of Object.entries(item.buff)){
        cosmeticBuffCache[buffKey] = (cosmeticBuffCache[buffKey] || 0) + value;
      }
    }
  }
  const cap = key === 'hp' || key === 'defense' ? .05 : .035;
  return Math.min(cap, cosmeticBuffCache[key] || 0);
}

function statMult(id, step = .08){
  if(!statMultCache) statMultCache = {};
  const key = `${id}:${step}`;
  if(statMultCache[key] === undefined) statMultCache[key] = Math.pow(1 + step, statLevel(id));
  return statMultCache[key];
}

function hpMax(){
  return Math.round((100 + statLevel('hp') * 18) * (1 + cosmeticBuff('hp')) * loadoutMult('hp'));
}

function safeHpMax(){
  const value = hpMax();
  return Number.isFinite(value) && value > 0 ? value : 100;
}

function visibleHpMax(){
  const value = Number(state.maxHp);
  return Number.isFinite(value) && value > 0 ? value : 100;
}

function visibleHp(){
  const max = visibleHpMax();
  const value = Number(state.hp);
  return Number.isFinite(value) ? Math.max(0, Math.min(max, value)) : max;
}

function hpFillPercent(){
  return visibleHp() / visibleHpMax() * 100;
}

function activeBoss(){
  return enemies.find(enemy => enemy?.boss) || null;
}

function bossHpInfo(){
  const boss = activeBoss();
  const visible = state.mode === 'play' && state.bossAlive && !!boss;
  const max = Math.max(1, Math.ceil(Number(boss?.maxHp ?? boss?.initialHp ?? boss?.hp) || 1));
  const hp = visible ? Math.max(0, Math.min(max, Math.ceil(Number(boss.hp) || 0))) : 0;
  return {
    visible,
    name: boss?.type?.name || 'BOSS',
    hp,
    max,
    percent: visible ? hp / max * 100 : 0
  };
}

function regenPerSecond(){
  return statLevel('regen') * .45 + specialRegenPerSecond();
}

function evasionChance(){
  return Math.min(.64, 1 - Math.pow(.96, statLevel('evasion')) + loadoutBuff('evasion') + specialEvasionBonus());
}

function defenseMultiplier(){
  return Math.max(.45, (1 - statLevel('defense') * .035 - cosmeticBuff('defense') - loadoutBuff('defense')) / shipMult('defense'));
}

function critChance(){
  return Math.min(.55, statLevel('critChance') * .03);
}

function critDamageMult(){
  return 1.5 + statLevel('critDamage') * .10;
}

function bulletSpeedDamageMult(){
  return 1 + statLevel('bulletSpeed') * .035 + cosmeticBuff('bulletSpeed') + loadoutBuff('bulletSpeed');
}

function tokenRewardMult(){
  return (1 + statLevel('tokenMult') * .08 + cosmeticBuff('token') + loadoutBuff('token')) * shipMult('token');
}

function collisionDamageAmount(enemy){
  const lv = statLevel('collisionDamage');
  if(lv <= 0) return 0;
  const bossScale = enemy?.boss ? .45 : 1;
  return Math.ceil((12 + state.wave * 1.6) * Math.pow(1.12, lv) * bossScale);
}

function xpThreshold(){
  return Math.floor(XP_BASE * Math.pow(1.55, state.level - 1));
}

function homeUpgradeCost(id){
  const def = homeUpgradeDef(id);
  const lv = homeUpgradeLevel(id);
  if(def.tier === 'base'){
    if(lv >= HOME_UPGRADE_CAP) return Infinity;
    return Math.floor(30 * Math.pow(1.34, lv));
  }
  return Math.floor(90 * Math.pow(1.24, lv));
}

function runBasicUpgradeCost(id){
  const def = BASIC_SKILL_DEFS_BY_ID[id];
  if(!def) return Infinity;
  const lv = runBasicLevel(id);
  if(def.tier === 'base'){
    return lv >= (def.cap || RUN_BASIC_CAP) ? Infinity : 1 + Math.floor(lv / 4);
  }
  return 2 + Math.floor(lv / 3);
}

function calculateTokenReward(){
  const scoreBonus = Math.floor(state.score / TOKEN_SCORE_UNIT);
  const waveBonus = Math.max(0, state.wave - 1) * TOKEN_WAVE_BONUS;
  const killBonus = Math.floor(state.kills * TOKEN_KILL_BONUS);
  const timeBonus = Math.floor(state.runTime * TOKEN_TIME_BONUS);
  return Math.max(0, Math.floor((scoreBonus + waveBonus + killBonus + timeBonus) * tokenRewardMult()));
}

function grantXp(amount){
  grantBasicPoints(amount);
  const gain = Math.max(1, Math.ceil(amount * statMult('xpMult', .10) * (1 + cosmeticBuff('xp') + loadoutBuff('xp')) * shipMult('xp') * specialXpMultiplier()));
  state.xp += gain;
  let leveled = false;
  while(state.xp >= xpThreshold()){
    state.xp -= xpThreshold();
    state.level++;
    state.skillPoints++;
    leveled = true;
  }
  if(leveled && state.mode === 'play') openLevelUp();
}

function grantBasicPoints(amount){
  state.basicPointMeter += Math.max(0, Number(amount) || 0);
  while(state.basicPointMeter >= BASIC_POINT_UNIT){
    state.basicPointMeter -= BASIC_POINT_UNIT;
    state.basicPoints++;
  }
}

function randomArrayItem(items){
  if(!items?.length) return null;
  return items[Math.floor(Math.random() * items.length)];
}

function rollUpgradeOptions(){
  const byFamily = new Map();
  for(const def of SPECIAL_UPGRADE_DEFS){
    if(!canOfferSpecialUpgrade(def.id)) continue;
    if(!byFamily.has(def.family)) byFamily.set(def.family, []);
    byFamily.get(def.family).push(def.id);
  }
  const options = [];
  const usedFamilies = new Set();
  const pushFromFamily = family => {
    if(options.length >= 3 || usedFamilies.has(family)) return false;
    const ids = byFamily.get(family);
    if(!ids?.length) return false;
    const id = randomArrayItem(ids);
    options.push(id);
    usedFamilies.add(family);
    return true;
  };

  if(!selectedSpecialInFamily('barrel')) pushFromFamily('barrel');

  const needsSupport = !selectedSpecialInFamily('guard') && !selectedSpecialInFamily('field');
  if(needsSupport){
    const supportFamily = randomArrayItem(['guard', 'field'].filter(family => byFamily.has(family) && !usedFamilies.has(family)));
    if(supportFamily) pushFromFamily(supportFamily);
  }

  let families = SPECIAL_FAMILY_ORDER.filter(family => byFamily.has(family) && !usedFamilies.has(family));
  while(options.length < 3 && families.length){
    const family = randomArrayItem(families);
    pushFromFamily(family);
    families = families.filter(item => item !== family);
  }
  return options;
}

function openLevelUp(){
  if(activePointer !== null) canvas.releasePointerCapture?.(activePointer);
  activePointer = null;
  state.pointer = 0;
  state.pointerThrottle = 0;
  resetTurnHold();
  resetTouchStick();
  state.rollVel *= .35;
  state.upgradeOptions = rollUpgradeOptions();
  if(!state.upgradeOptions.length) return;
  setMode('levelup');
}

function applyRunUpgrade(id){
  if(state.skillPoints <= 0) return;
  const specialDef = specialUpgradeDef(id);
  if(!specialDef || !canOfferSpecialUpgrade(id)) return;
  state.specialUpgrades[id] = Math.min(specialDef.max, specialUpgradeLevel(id) + 1);
  invalidateWeaponCache();
  syncMagazineCapacity(true);
  if(!state.reloading) state.reloadTotal = reloadDuration();
  state.skillPoints--;
  if(state.skillPoints > 0){
    state.upgradeOptions = rollUpgradeOptions();
    if(state.upgradeOptions.length){
      renderUi2();
    }else{
      setMode('play');
    }
  }else{
    state.upgradeOptions = [];
    setMode('play');
  }
}

function buyRunBasicUpgrade(id){
  if(!BASIC_SKILL_DEFS_BY_ID[id] || !isRunBasicUnlocked(id) || isRunBasicMaxed(id)) return;
  const cost = runBasicUpgradeCost(id);
  if(!Number.isFinite(cost) || state.basicPoints < cost) return;
  const beforeMax = visibleHpMax();
  state.basicPoints -= cost;
  state.statLevels[id] = runBasicLevel(id) + 1;
  invalidateStatCache();
  if(id === 'magazine') syncMagazineCapacity(true);
  if(id === 'reload' && !state.reloading) state.reloadTotal = reloadDuration();
  if(id === 'hp'){
    state.maxHp = safeHpMax();
    state.hp = Math.min(state.maxHp, state.hp + Math.max(0, state.maxHp - beforeMax) + 18);
  }
  if(state.basicPoints <= 0){
    state.basicPickerOpen = false;
    renderUi2();
    return;
  }
  state.basicPickerOpen = true;
  if(state.mode === 'play' && refreshHudBasicUpgradePicker()) return;
  renderUi2();
}

function buyHomeUpgrade(id){
  if(!isHomeUpgradeUnlocked(id) || isHomeUpgradeMaxed(id)) return;
  const cost = homeUpgradeCost(id);
  if(!spendTokens(cost)) return;
  state.homeUpgrades[id] = homeUpgradeLevel(id) + 1;
  invalidateStatCache();
  if(id === 'magazine') syncMagazineCapacity(true);
  if(id === 'reload' && !state.reloading) state.reloadTotal = reloadDuration();
  state.maxHp = safeHpMax();
  state.hp = Math.min(state.maxHp, state.hp || state.maxHp);
  saveProgress();
  renderUi2();
}

function buyShip(id){
  const ship = SHIP_BY_ID[id];
  if(!ship) return;
  if(shipOwned(id)){
    equipShip(id);
    return;
  }
  if(!spendTokens(ship.cost)) return;
  state.garage.ownedShips[id] = 1;
  state.garage.selectedShipId = id;
  state.storePreviewShipId = id;
  invalidateLoadoutCache();
  markHomeShipPartsDirty();
  refreshLoadoutVitals();
  saveProgress();
  renderUi2();
}

function partOwned(id){
  return !!state.garage?.ownedParts?.[id];
}

function partsForType(type){
  return PARTS_BY_TYPE[type] || EMPTY_PART_LIST;
}

function partCost(part){
  return Math.max(0, Math.floor(Number(part?.cost) || 0));
}

function buyPart(id){
  const part = PART_BY_ID[id];
  if(!part) return;
  if(partOwned(id)){
    setMode('garage');
    return;
  }
  const cost = partCost(part);
  if(!spendTokens(cost)) return;
  state.garage.ownedParts[id] = 1;
  const equipped = state.garage.equippedParts[part.type] || Array(3).fill(null);
  state.garage.equippedParts[part.type] = equipped;
  const slots = shipSlotCount(part.type);
  const emptySlot = equipped.slice(0, slots).findIndex(value => !value);
  if(slots > 0 && emptySlot >= 0 && !equipped.includes(id)){
    equipped[emptySlot] = id;
  }
  invalidateLoadoutCache();
  markHomeShipPartsDirty();
  refreshLoadoutVitals();
  saveProgress();
  renderUi2();
}

function equipShip(id){
  if(!SHIP_BY_ID[id] || !shipOwned(id)) return;
  state.garage.selectedShipId = id;
  state.storePreviewShipId = id;
  invalidateLoadoutCache();
  refreshLoadoutVitals();
  saveProgress();
  applyCosmetics();
  renderUi2();
}

function equipPart(type, index, id){
  if(!PART_TYPES.includes(type)) return;
  const slot = Math.max(0, Math.floor(Number(index) || 0));
  if(slot >= shipSlotCount(type)) return;
  const equipped = state.garage.equippedParts[type] || Array(3).fill(null);
  state.garage.equippedParts[type] = equipped;
  if(!id || id === 'none'){
    equipped[slot] = null;
  }else{
    const part = PART_BY_ID[id];
    if(!part || part.type !== type || !state.garage.ownedParts[id]) return;
    for(let i=0;i<equipped.length;i++){
      if(equipped[i] === id) equipped[i] = null;
    }
    equipped[slot] = id;
  }
  invalidateLoadoutCache();
  markHomeShipPartsDirty();
  refreshLoadoutVitals();
  saveProgress();
  renderUi2();
}

function cosmeticItem(id){
  return COSMETIC_BY_ID[id];
}

function equippedCosmetic(type){
  return cosmeticItem(state.cosmetics?.equipped?.[type] || DEFAULT_COSMETICS[type]) || cosmeticItem(DEFAULT_COSMETICS[type]);
}

function rollGachaItem(){
  const total = COSMETIC_RARITIES.reduce((sum, rarity) => sum + rarity.weight, 0);
  let roll = Math.random() * total;
  const rarity = COSMETIC_RARITIES.find(r => (roll -= r.weight) <= 0) || COSMETIC_RARITIES[0];
  const pool = COSMETIC_ITEMS.filter(item => item.rarity === rarity.id);
  return pool[Math.floor(Math.random() * pool.length)] || COSMETIC_ITEMS[0];
}

function rollGacha(){
  if(!spendTokens(GACHA_COST)) return;
  const item = rollGachaItem();
  const ownedCount = Number(state.cosmetics.owned[item.id]) || 0;
  const duplicate = ownedCount > 0;
  state.cosmetics.owned[item.id] = ownedCount + 1;
  if(!state.cosmetics.equipped[item.type]) state.cosmetics.equipped[item.type] = item.id;
  if(duplicate && !hasUnlimitedTokens()){
    state.tokens += COSMETIC_RARITY_BY_ID[item.rarity].refund;
  }
  cosmeticBuffCache = null;
  state.lastGacha = {id:item.id, duplicate};
  saveProgress();
  applyCosmetics();
  renderUi2();
}

function equipCosmetic(id){
  const item = cosmeticItem(id);
  if(!item || !state.cosmetics.owned[id]) return;
  state.cosmetics.equipped[item.type] = id;
  saveProgress();
  applyCosmetics();
  renderUi2();
}

function applyColor(material, color){
  if(material?.color) material.color.setHex(color);
}

function applyLineColor(material, color){
  if(material?.color) material.color.setHex(color);
}

function colorHexValue(color, fallback = 0x8eefff){
  if(typeof color === 'number' && Number.isFinite(color)) return color & 0xffffff;
  if(typeof color === 'string'){
    let value = color.trim();
    if(value.startsWith('#')) value = value.slice(1);
    if(value.length === 3) value = value.split('').map(ch => ch + ch).join('');
    const parsed = Number.parseInt(value, 16);
    if(Number.isFinite(parsed)) return parsed & 0xffffff;
  }
  return fallback;
}

function setMaterialColorHexCached(material, color){
  if(!material?.color) return;
  const next = colorHexValue(color);
  if(material.userData.lastColorHex === next) return;
  material.userData.lastColorHex = next;
  material.color.setHex(next);
}

function setMaterialOpacityCached(material, opacity, epsilon = .003){
  if(!material || material.opacity === undefined) return;
  if(Math.abs((material.userData.lastOpacity ?? -1) - opacity) < epsilon) return;
  material.userData.lastOpacity = opacity;
  material.opacity = opacity;
}

function blendHex(a, b, amount = .5){
  const color = new THREE.Color(colorHexValue(a));
  color.lerp(new THREE.Color(colorHexValue(b)), clamp(amount, 0, 1));
  return color.getHex();
}

function cosmeticVisualState(){
  const bulletItem = equippedCosmetic('bulletSkin');
  const armorItem = equippedCosmetic('armorSkin');
  const coatItem = equippedCosmetic('shipCoat');
  const bullet = {...(BULLET_VISUAL_PROFILES[bulletItem.id] || bulletItem.colors || {})};
  const armor = {...(ARMOR_VISUAL_PROFILES[armorItem.id] || armorItem.colors || {})};
  const coat = {...(COAT_VISUAL_PROFILES[coatItem.id] || coatItem.colors || {})};
  bullet.shot = colorHexValue(bullet.shot ?? bulletItem.colors?.shot, 0x9cf5ff);
  bullet.glow = colorHexValue(bullet.glow ?? bulletItem.colors?.glow, 0x1ed6ff);
  bullet.core = colorHexValue(bullet.core ?? bullet.glow, bullet.glow);
  bullet.flare = bullet.flare ?? .34;
  bullet.pulse = bullet.pulse ?? 1;
  armor.plate = colorHexValue(armor.plate ?? armorItem.colors?.plate, 0xf6f9fa);
  armor.panel = colorHexValue(armor.panel ?? armorItem.colors?.panel, 0x102436);
  armor.trim = colorHexValue(armor.trim ?? armor.plate, 0xd8e2ea);
  armor.secondary = colorHexValue(armor.secondary ?? bullet.glow, bullet.glow);
  armor.glass = colorHexValue(armor.glass ?? bullet.shot, bullet.shot);
  armor.metalness = armor.metalness ?? .66;
  armor.roughness = armor.roughness ?? .15;
  armor.glow = armor.glow ?? .52;
  coat.hull = colorHexValue(coat.hull ?? coatItem.colors?.hull, 0x06111d);
  coat.wing = colorHexValue(coat.wing ?? coatItem.colors?.wing, 0x0c1a2b);
  coat.line = colorHexValue(coat.line ?? coatItem.colors?.line, 0x82d7ff);
  coat.trim = colorHexValue(coat.trim ?? armor.trim, armor.trim);
  coat.hot = colorHexValue(coat.hot ?? bullet.glow, bullet.glow);
  coat.engine = colorHexValue(coat.engine ?? bullet.glow, bullet.glow);
  coat.metalness = coat.metalness ?? .80;
  coat.roughness = coat.roughness ?? .18;
  coat.glow = coat.glow ?? 1;
  coat.decalScale = coat.decalScale ?? 1;
  return {bulletItem, armorItem, coatItem, bullet, armor, coat};
}

function applyMeshFinish(material, color, options = {}){
  if(!material) return;
  if(material.color) material.color.setHex(colorHexValue(color));
  if(material.emissive && options.emissive != null) material.emissive.setHex(colorHexValue(options.emissive));
  if(options.emissiveIntensity != null && material.emissiveIntensity !== undefined) material.emissiveIntensity = options.emissiveIntensity;
  if(options.metalness != null && material.metalness !== undefined) material.metalness = options.metalness;
  if(options.roughness != null && material.roughness !== undefined) material.roughness = options.roughness;
  if(options.opacity != null && material.opacity !== undefined){
    material.opacity = options.opacity;
    material.transparent = options.opacity < 1 || material.transparent;
  }
  material.needsUpdate = true;
}

function applyLineFinish(material, color, opacity){
  if(!material) return;
  if(material.color) material.color.setHex(colorHexValue(color));
  if(opacity != null && material.opacity !== undefined){
    material.opacity = opacity;
    material.transparent = opacity < 1 || material.transparent;
  }
  material.needsUpdate = true;
}

function applySkinKitVisual(kit, visual, frameAccent = null){
  if(!kit?.groups || !visual) return;
  const activeId = visual.coatItem?.id || DEFAULT_COSMETICS.shipCoat;
  for(const [id, group] of Object.entries(kit.groups)){
    group.visible = id === activeId;
  }
  const frameMix = frameAccent == null ? visual.coat.line : blendHex(visual.coat.line, frameAccent, .22);
  applyMeshFinish(kit.materials.accent, frameMix, {emissive:visual.coat.line, emissiveIntensity:.72 * visual.coat.glow, opacity:.90});
  applyMeshFinish(kit.materials.hot, blendHex(visual.coat.hot, visual.armor.secondary, .24), {emissive:visual.coat.hot, emissiveIntensity:.86 * visual.coat.glow, opacity:.86});
  applyMeshFinish(kit.materials.plate, blendHex(visual.armor.plate, visual.coat.trim, .32), {emissive:visual.armor.secondary, emissiveIntensity:.24 + visual.armor.glow * .22, opacity:.82});
  applyMeshFinish(kit.materials.glow, visual.bullet.core, {opacity:.40 + visual.bullet.flare * .42});
  applyLineFinish(kit.materials.line, frameMix, .62 + visual.coat.glow * .10);
  applyLineFinish(kit.materials.softLine, blendHex(visual.armor.trim, visual.bullet.glow, .35), .36 + visual.armor.glow * .18);
  kit.root.scale.setScalar(visual.coat.decalScale || 1);
  kit.root.visible = true;
}

function updateSkinKitAnimation(kit, t){
  if(!kit?.root?.visible) return;
  const pulse = .78 + Math.sin(t * 3.2) * .10;
  if(kit.materials?.glow){
    kit.materials.glow.opacity = Math.max(.30, pulse);
  }
  for(const ring of kit.rings || []){
    ring.rotation.z += .010 + Math.sin(t * .7) * .002;
  }
}

function applyPlayerCosmeticFinish(visual = cosmeticVisualState(), frameAccent = colorHexValue(currentShip().color)){
  if(!shared?.materials || !visual) return;
  const coatLine = blendHex(visual.coat.line, frameAccent, .18);
  const coreColor = blendHex(visual.bullet.core, frameAccent, .18);
  applyMeshFinish(shared.materials.shot, visual.bullet.core || visual.bullet.shot);
  applyMeshFinish(shared.materials.bulletGlow, visual.bullet.glow, {opacity:Math.min(.78, .48 + visual.bullet.flare * .55)});
  applyMeshFinish(shared.materials.shotGlow, visual.bullet.glow, {opacity:Math.min(.64, .34 + visual.bullet.flare * .38)});
  applyMeshFinish(shared.materials.player, visual.coat.hull, {emissive:blendHex(visual.coat.hull, visual.coat.line, .46), emissiveIntensity:.62 * visual.coat.glow, metalness:visual.coat.metalness, roughness:visual.coat.roughness});
  applyMeshFinish(shared.materials.playerEngine, blendHex(visual.coat.hull, visual.coat.engine, .16), {emissive:visual.coat.engine, emissiveIntensity:.24 + visual.bullet.flare * .42, metalness:.82, roughness:.20});
  applyMeshFinish(shared.materials.playerWing, visual.coat.wing, {emissive:blendHex(visual.coat.wing, visual.coat.line, .45), emissiveIntensity:.50 * visual.coat.glow, metalness:Math.max(.62, visual.coat.metalness - .06), roughness:visual.coat.roughness + .03});
  applyMeshFinish(shared.materials.playerPlate, visual.armor.plate, {emissive:blendHex(visual.armor.panel, visual.armor.secondary, .44), emissiveIntensity:visual.armor.glow, metalness:visual.armor.metalness, roughness:visual.armor.roughness});
  applyMeshFinish(shared.materials.playerPanel, visual.armor.panel, {emissive:blendHex(visual.armor.panel, visual.coat.line, .42), emissiveIntensity:visual.armor.glow * .92, metalness:Math.max(.62, visual.armor.metalness), roughness:visual.armor.roughness + .03});
  applyMeshFinish(shared.materials.playerGlass, blendHex(visual.armor.glass, visual.bullet.shot, .48), {emissive:visual.bullet.glow, emissiveIntensity:1.20 * visual.bullet.pulse, opacity:.82});
  applyMeshFinish(shared.materials.playerCore, coreColor);
  applyMeshFinish(shared.materials.playerGold, visual.armor.trim, {opacity:.88});
  applyMeshFinish(shared.materials.playerRose, visual.coat.hot, {opacity:.82});
  applyLineFinish(shared.materials.playerEdge, coatLine, .72);
  applyLineFinish(shared.materials.playerGoldLine, visual.armor.trim, .70);
  applyLineFinish(shared.materials.playerRoseLine, blendHex(visual.coat.hot, visual.bullet.glow, .35), .64);
  applyLineFinish(shared.materials.railCyan, coatLine, .48);
  applySkinKitVisual(player?.skinKit, visual, frameAccent);
  applyAfterburnerVisual(player?.afterburners, visual, frameAccent);
}

function applyHomeShipCosmeticFinish(ship = visualPreviewShip(), visual = cosmeticVisualState()){
  if(!homeShip?.materials || !visual) return;
  const frameAccent = colorHexValue(ship?.color || visual.coat.line);
  const coatLine = blendHex(visual.coat.line, frameAccent, .22);
  applyMeshFinish(homeShip.materials.hull, visual.coat.hull, {emissive:blendHex(visual.coat.hull, visual.coat.line, .50), emissiveIntensity:1.02 * visual.coat.glow, metalness:visual.coat.metalness, roughness:visual.coat.roughness});
  applyMeshFinish(homeShip.materials.engine, blendHex(visual.coat.hull, visual.coat.engine, .18), {emissive:visual.coat.engine, emissiveIntensity:.26 + visual.bullet.flare * .36, metalness:.82, roughness:.20});
  applyMeshFinish(homeShip.materials.wing, visual.coat.wing, {emissive:blendHex(visual.coat.wing, visual.coat.line, .48), emissiveIntensity:.70 * visual.coat.glow, metalness:Math.max(.62, visual.coat.metalness - .06), roughness:visual.coat.roughness + .02});
  applyMeshFinish(homeShip.materials.plate, visual.armor.plate, {emissive:blendHex(visual.armor.panel, visual.armor.secondary, .45), emissiveIntensity:visual.armor.glow * .58, metalness:visual.armor.metalness, roughness:visual.armor.roughness});
  applyMeshFinish(homeShip.materials.panel, visual.armor.panel, {emissive:blendHex(visual.armor.panel, visual.coat.line, .45), emissiveIntensity:visual.armor.glow, metalness:Math.max(.62, visual.armor.metalness), roughness:visual.armor.roughness + .02});
  applyMeshFinish(homeShip.materials.core, blendHex(visual.bullet.core, frameAccent, .16));
  applyMeshFinish(homeShip.materials.glass, blendHex(visual.armor.glass, visual.bullet.shot, .46), {emissive:visual.bullet.glow, emissiveIntensity:1.65 * visual.bullet.pulse, opacity:.84});
  applyMeshFinish(homeShip.materials.trim, visual.armor.trim, {opacity:.86});
  applyMeshFinish(homeShip.materials.accent, blendHex(visual.coat.hot, visual.bullet.glow, .30), {opacity:.78});
  applyLineFinish(homeShip.materials.edge, coatLine, .70);
  applyLineFinish(homeShip.materials.goldLine, visual.armor.trim, .66);
  applyLineFinish(homeShip.materials.roseLine, blendHex(visual.coat.hot, visual.bullet.glow, .34), .62);
  applySkinKitVisual(homeShip.skinKit, visual, frameAccent);
  applyAfterburnerVisual(homeShip.afterburners, visual, frameAccent);
}

function applyHomeShipFrameAccent(ship){
  if(!homeShip?.materials || !ship) return;
  const accent = colorHexValue(ship.color);
  const visual = cosmeticVisualState();
  applyHomeShipCosmeticFinish(ship, visual);
  applyColor(homeShip.materials.core, blendHex(visual.bullet.core, accent, .18));
  if(homeShip.materials.glass?.emissive) homeShip.materials.glass.emissive.setHex(blendHex(visual.bullet.glow, accent, .14));
  if(homeShip.materials.panel?.emissive) homeShip.materials.panel.emissive.setHex(blendHex(visual.armor.secondary, accent, .16));
}

function applyCosmetics(){
  if(!shared?.materials) return;
  const visual = cosmeticVisualState();
  applyPlayerCosmeticFinish(visual);
  applyHomeShipCosmeticFinish(visualPreviewShip(), visual);
  markHomeShipPartsDirty();
  syncHomeShipParts(true);
}

function markHomeShipPartsDirty(){
  previewPartVisualKey = '';
  homeShipPartsDirty = true;
}

function syncHomeShipParts(force = false){
  if(!homeShip?.partVisuals) return;
  if(!force && !homeShipPartsDirty) return;
  const ship = visualPreviewShip();
  const equippedKey = PART_TYPES
    .map(type => `${type}:${(state.garage?.equippedParts?.[type] || []).join(',')}:${shipSlotCount(type, ship)}`)
    .join('|');
  const key = `${ship.id}|${equippedKey}`;
  if(!force && key === previewPartVisualKey){
    homeShipPartsDirty = false;
    return;
  }
  previewPartVisualKey = key;
  homeShipPartsDirty = false;
  applyHomeShipFrameAccent(ship);
  if(homeShip.variantVisuals){
    for(const [id, group] of Object.entries(homeShip.variantVisuals)){
      group.visible = id === ship.id;
    }
  }
  for(const type of PART_TYPES){
    const equipped = state.garage?.equippedParts?.[type] || [];
    const slots = shipSlotCount(type, ship);
    for(let index=0; index<3; index++){
      const group = homeShip.partVisuals[`${type}:${index}`];
      if(!group) continue;
      group.visible = false;
    }
    const layout = HOME_PART_SLOT_LAYOUTS[type]?.[Math.min(3, slots)] || [0, 1, 2];
    for(let slotIndex=0; slotIndex<Math.min(3, slots); slotIndex++){
      const part = PART_BY_ID[equipped[slotIndex]];
      if(!part) continue;
      const visualIndex = layout[slotIndex] ?? slotIndex;
      const group = homeShip.partVisuals[`${type}:${visualIndex}`];
      if(!group) continue;
      group.visible = true;
      const material = group.userData.material;
      if(material?.color) material.color.set(part.color);
      if(material?.emissive) material.emissive.set(part.color);
      if(material) material.emissiveIntensity = type === 'drone' ? 1.35 : .95;
      const power = type === 'barrel' ? 1 + slotIndex * .06 : type === 'drone' ? .95 + slotIndex * .05 : 1;
      group.scale.setScalar(power);
    }
  }
}

function syncPlayerShipVariant(){
  if(!player?.variantVisuals) return;
  const ship = currentShip();
  const accent = colorHexValue(ship.color);
  const profile = currentShipVisualProfile();
  applyColor(shared.materials.playerCore, accent);
  applyColor(shared.materials.playerGlass, accent);
  applyLineColor(shared.materials.playerEdge, accent);
  applyLineColor(shared.materials.playerRoseLine, accent);
  if(shared.materials.playerGlass?.emissive) shared.materials.playerGlass.emissive.setHex(accent);
  player.body?.scale.set(...profile.body);
  player.wings?.scale.set(...profile.wing);
  player.rightWing?.scale.set(...profile.wing);
  player.nose?.scale.set(...profile.nose);
  player.aura?.scale.setScalar(profile.aura);
  for(const [id, group] of Object.entries(player.variantVisuals)){
    group.visible = id === DEFAULT_SHIP_ID || id === ship.id;
  }
  applyPlayerCosmeticFinish(cosmeticVisualState(), accent);
}

